#!/bin/bash
# generated by run_group.py
set -o pipefail
__regress_fails=0
trap '__rc=$?; echo "[regress] command failed (rc=$__rc): $BASH_COMMAND" >&2; __regress_fails=$((__regress_fails + 1))' ERR
export HF_MODEL=openai/gpt-oss-120b TT_CACHE_PATH=/mnt/models/huggingface/tt_cache/openai--gpt-oss-120b/ TT_MM_THROTTLE_PERF=2
# Tensor cache is pre-built on the NAS — skip loading model weights by default.
# Check mlperf-write-access in the workflow to load weights and regenerate the cache.
SKIP_MODEL_LOAD="--skip-model-load"
[ "${MLPERF_READ_ONLY:-true}" = "false" ] && SKIP_MODEL_LOAD=""
pytest models/demos/gpt_oss/demo/text_demo.py --timeout 1500 $SKIP_MODEL_LOAD

exit $(( __regress_fails > 0 ? 1 : 0 ))
